-- Run only in the isolated CI database named cpwallet_test. Never production.
\set ON_ERROR_STOP on
DO $$ BEGIN IF current_database()<>'cpwallet_test' THEN RAISE EXCEPTION 'Isolated fixture database required'; END IF; END $$;
DO $$ BEGIN
 IF NOT EXISTS(SELECT FROM pg_roles WHERE rolname='anon') THEN CREATE ROLE anon; END IF;
 IF NOT EXISTS(SELECT FROM pg_roles WHERE rolname='authenticated') THEN CREATE ROLE authenticated; END IF;
 IF NOT EXISTS(SELECT FROM pg_roles WHERE rolname='service_role') THEN CREATE ROLE service_role; END IF;
END $$;
CREATE TABLE profiles(id uuid PRIMARY KEY,role text);
CREATE TABLE wallets(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,user_id uuid UNIQUE REFERENCES profiles(id),balance numeric NOT NULL DEFAULT 0,pending_balance numeric NOT NULL DEFAULT 0,total_earned numeric NOT NULL DEFAULT 0,total_spent numeric NOT NULL DEFAULT 0,total_withdrawn numeric NOT NULL DEFAULT 0,status text NOT NULL DEFAULT 'active',created_at timestamptz DEFAULT now(),updated_at timestamptz DEFAULT now());
CREATE TABLE wallet_topups(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,user_id uuid,wallet_id bigint,amount numeric,payment_method text,payment_note text,status text,processed_at timestamptz,created_at timestamptz DEFAULT now(),sender_name text,sender_account text,payment_image text,admin_note text);
CREATE TABLE wallet_transactions(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,wallet_id bigint,user_id uuid,type text CHECK(type IN ('deposit','buyer_order_payment','order_refund','refund')),transaction_type text,amount numeric,balance_before numeric,balance_after numeric,order_id bigint,description text,status text,metadata jsonb DEFAULT '{}',created_at timestamptz DEFAULT now());
CREATE UNIQUE INDEX fixture_payment_unique ON wallet_transactions(order_id,type) WHERE order_id IS NOT NULL AND type='buyer_order_payment';
CREATE TABLE orders(id bigint PRIMARY KEY,buyer_id uuid,seller_id uuid,product_id bigint,variant_id bigint,quantity integer,total_amount numeric,total_price numeric,currency_code text DEFAULT 'IDR',status text DEFAULT 'pending_payment',payment_status text DEFAULT 'pending',invoice_number text,paypal_order_id text,payment_method text,paid_at timestamptz,escrow_status text DEFAULT 'pending',seller_payout_status text DEFAULT 'pending',reservation_status text,refund_reference text,refund_amount numeric,refund_reason text,refunded_at timestamptz,refunded_by uuid,updated_at timestamptz);
CREATE TABLE products(id bigint PRIMARY KEY,stock integer,updated_at timestamptz);
CREATE TABLE product_variants(id bigint PRIMARY KEY,product_id bigint,stock integer,updated_at timestamptz);
CREATE TABLE product_stock_reservations(order_id bigint UNIQUE,status text,released_at timestamptz,release_reason text,updated_at timestamptz);
CREATE TABLE notifications(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,user_id uuid,type text,title text,message text,link_url text,is_read boolean);
CREATE FUNCTION cp_is_admin(user_id uuid) RETURNS boolean LANGUAGE sql AS $$ SELECT coalesce((SELECT role='admin' FROM profiles WHERE id=user_id),false) $$;
CREATE FUNCTION cp_consume_order_reservation(p_order_id bigint,p_buyer_id uuid) RETURNS jsonb LANGUAGE plpgsql AS $$ BEGIN
 IF current_setting('fixture.fail_stock',true)='true' THEN RAISE EXCEPTION 'Order reservation expired before payment completed.'; END IF;
 INSERT INTO product_stock_reservations VALUES(p_order_id,'consumed',NULL,NULL,now()) ON CONFLICT(order_id) DO UPDATE SET status='consumed';
 RETURN '{}'; END $$;
-- Legacy entry point exists so the migration must remove its previous grants.
CREATE FUNCTION checkout_wallet_order(p_product_id bigint,p_buyer_note text,p_coupon_id bigint,p_discount_amount numeric) RETURNS jsonb LANGUAGE sql AS $$ SELECT '{}'::jsonb $$;
GRANT EXECUTE ON FUNCTION checkout_wallet_order(bigint,text,bigint,numeric) TO anon,authenticated;

\ir ../../supabase/migrations/20260916173800_cpwallet_payments.sql

INSERT INTO profiles VALUES('00000000-0000-4000-8000-000000000001','buyer'),('00000000-0000-4000-8000-000000000002','seller'),('00000000-0000-4000-8000-000000000003','admin');
INSERT INTO wallets(user_id,balance) VALUES('00000000-0000-4000-8000-000000000001',50000);
INSERT INTO products VALUES(1,20,now());
INSERT INTO product_variants VALUES(1,1,5,now());
INSERT INTO orders(id,buyer_id,seller_id,product_id,variant_id,quantity,total_amount,total_price) VALUES
 (1,'00000000-0000-4000-8000-000000000001','00000000-0000-4000-8000-000000000002',1,1,2,60000,60000),
 (2,'00000000-0000-4000-8000-000000000001','00000000-0000-4000-8000-000000000002',1,NULL,1,60000,60000),
 (3,'00000000-0000-4000-8000-000000000001','00000000-0000-4000-8000-000000000002',1,NULL,1,999999,999999);
DO $$
DECLARE buyer uuid:='00000000-0000-4000-8000-000000000001'; other_user uuid:='00000000-0000-4000-8000-000000000002'; admin_id uuid:='00000000-0000-4000-8000-000000000003';
 q jsonb:='{"amount_idr":100000,"display_amount":100000,"display_currency":"IDR","idr_per_unit":1,"rate_date":"2026-09-16","charge_amount":100000,"charge_currency":"IDR"}';
 t jsonb; t2 jsonb; id uuid; invoice text; caught boolean; balance_before numeric;
BEGIN
 t:=cp_create_wallet_topup_quote(buyer,'00000000-0000-4000-8000-000000000010','doku',q); id:=(t->>'id')::uuid; invoice:='CPW-'||replace(id::text,'-','');
 t2:=cp_create_wallet_topup_quote(buyer,'00000000-0000-4000-8000-000000000010','doku',q);
 ASSERT t2->>'id'=t->>'id' AND (SELECT count(*) FROM cp_wallet_topup_intents)=1,'duplicate quote must reuse the same intent';
 caught:=false; BEGIN PERFORM cp_start_wallet_topup(id,other_user); EXCEPTION WHEN raise_exception THEN caught:=true; END; ASSERT caught,'ownership required';
 t:=cp_start_wallet_topup(id,buyer); ASSERT t->>'start_claimed'='true';
 t:=cp_start_wallet_topup(id,buyer); ASSERT NOT t ? 'start_claimed','only one caller may initiate provider payment';
 caught:=false; BEGIN PERFORM cp_credit_wallet_topup(id,'doku',invoice,invoice,99999,'IDR'); EXCEPTION WHEN raise_exception THEN caught:=true; END; ASSERT caught,'reject underpayment';
 caught:=false; BEGIN PERFORM cp_credit_wallet_topup(id,'doku',invoice,invoice,100000,'USD'); EXCEPTION WHEN raise_exception THEN caught:=true; END; ASSERT caught,'reject wrong currency';
 caught:=false; BEGIN PERFORM cp_credit_wallet_topup(id,'paypal',invoice,invoice,100000,'IDR'); EXCEPTION WHEN raise_exception THEN caught:=true; END; ASSERT caught,'reject wrong provider';
 caught:=false; BEGIN PERFORM cp_credit_wallet_topup(id,'doku','WRONG',invoice,100000,'IDR'); EXCEPTION WHEN raise_exception THEN caught:=true; END; ASSERT caught,'reject invoice mismatch';
 ASSERT (SELECT balance FROM wallets WHERE user_id=buyer)=50000,'mismatches must not credit';
 t:=cp_credit_wallet_topup(id,'doku',invoice,invoice,100000,'IDR'); ASSERT t->>'already_credited'='false';
 t:=cp_credit_wallet_topup(id,'doku',invoice,invoice,100000,'IDR'); ASSERT t->>'already_credited'='true';
 ASSERT (SELECT balance FROM wallets WHERE user_id=buyer)=150000;
 ASSERT (SELECT count(*) FROM wallet_transactions WHERE type='deposit')=1 AND (SELECT count(*) FROM wallet_topups)=1,'one payment one credit';
 caught:=false; BEGIN PERFORM cp_credit_wallet_topup(id,'doku',invoice,'SECOND',100000,'IDR'); EXCEPTION WHEN raise_exception THEN caught:=true; END; ASSERT caught;
 caught:=false; BEGIN PERFORM pay_order_with_wallet(1,other_user); EXCEPTION WHEN raise_exception THEN caught:=true; END; ASSERT caught;
 caught:=false; BEGIN PERFORM pay_order_with_wallet(3,buyer); EXCEPTION WHEN raise_exception THEN caught:=true; END; ASSERT caught,'no overdraft';
 UPDATE wallets SET status='frozen' WHERE user_id=buyer;
 caught:=false; BEGIN PERFORM pay_order_with_wallet(1,buyer); EXCEPTION WHEN raise_exception THEN caught:=true; END; ASSERT caught,'frozen spending denied';
 UPDATE wallets SET status='active' WHERE user_id=buyer;
 PERFORM set_config('fixture.fail_stock','true',true);
 caught:=false; BEGIN PERFORM pay_order_with_wallet(1,buyer); EXCEPTION WHEN raise_exception THEN caught:=true; END; ASSERT caught,'stock errors roll back payment';
 ASSERT (SELECT balance FROM wallets WHERE user_id=buyer)=150000;
 PERFORM set_config('fixture.fail_stock','false',true);
 t:=pay_order_with_wallet(1,buyer); ASSERT t->>'already_paid'='false';
 t:=pay_order_with_wallet(1,buyer); ASSERT t->>'already_paid'='true';
 ASSERT (SELECT balance FROM wallets WHERE user_id=buyer)=90000 AND (SELECT total_spent FROM wallets WHERE user_id=buyer)=60000;
 ASSERT (SELECT count(*) FROM wallet_transactions WHERE order_id=1 AND type='buyer_order_payment')=1;
 caught:=false; BEGIN PERFORM cp_claim_external_order_payment(1,buyer); EXCEPTION WHEN raise_exception THEN caught:=true; END; ASSERT caught,'external payment cannot start after wallet purchase';
 PERFORM cp_claim_external_order_payment(2,buyer);
 caught:=false; BEGIN PERFORM pay_order_with_wallet(2,buyer); EXCEPTION WHEN raise_exception THEN caught:=true; END; ASSERT caught,'wallet cannot pay an order with an external attempt';
 caught:=false; BEGIN PERFORM cp_refund_order_to_wallet(1,buyer,'test'); EXCEPTION WHEN raise_exception THEN caught:=true; END; ASSERT caught,'admin only refund';
 caught:=false; BEGIN PERFORM cp_refund_order_to_wallet(2,admin_id,'test'); EXCEPTION WHEN raise_exception THEN caught:=true; END; ASSERT caught,'unpaid orders cannot produce a refund';
 UPDATE orders SET escrow_status='released' WHERE orders.id=1;
 caught:=false; BEGIN PERFORM cp_refund_order_to_wallet(1,admin_id,'test'); EXCEPTION WHEN raise_exception THEN caught:=true; END; ASSERT caught,'released seller payout must block refund';
 UPDATE orders SET escrow_status='holding',refund_reference='EXTERNAL-PENDING' WHERE orders.id=1;
 caught:=false; BEGIN PERFORM cp_refund_order_to_wallet(1,admin_id,'test'); EXCEPTION WHEN raise_exception THEN caught:=true; END; ASSERT caught,'do not credit over an external refund';
 UPDATE orders SET refund_reference=NULL WHERE orders.id=1;
 t:=cp_refund_order_to_wallet(1,admin_id,'Fixture approved refund'); ASSERT t->>'already_refunded'='false';
 t:=cp_refund_order_to_wallet(1,admin_id,'Fixture replay'); ASSERT t->>'already_refunded'='true';
 ASSERT (SELECT balance FROM wallets WHERE user_id=buyer)=150000;
 ASSERT (SELECT stock FROM product_variants WHERE product_variants.id=1)=7 AND (SELECT stock FROM products WHERE products.id=1)=20,'refund restores only the variant once';
 ASSERT (SELECT count(*) FROM wallet_transactions WHERE order_id=1 AND type='order_refund')=1;
 UPDATE orders SET payment_status='paid',status='paid',escrow_status='holding' WHERE orders.id=2;
 INSERT INTO product_stock_reservations(order_id,status) VALUES(2,'released');
 t:=cp_refund_order_to_wallet(2,admin_id,'Previously released reservation');
 ASSERT (SELECT stock FROM products WHERE products.id=1)=20,'an already released reservation must not restore stock twice';
 PERFORM set_config('request.jwt.claims','{"role":"service_role"}',true);
 t:=credit_wallet_paypal_topup(other_user,'FIXTURE-LEGACY',15000,1);
 t:=credit_wallet_paypal_topup(other_user,'FIXTURE-LEGACY',15000,1);
 ASSERT t->>'duplicated'='true' AND (SELECT balance FROM wallets WHERE user_id=other_user)=15000,'legacy capture supports modern JWT claims and credits once';
 t:=cp_create_wallet_topup_quote(buyer,'00000000-0000-4000-8000-000000000011','doku',q); id:=(t->>'id')::uuid;
 UPDATE cp_wallet_topup_intents SET quote_expires_at=now()-interval '1 second' WHERE cp_wallet_topup_intents.id=(t->>'id')::uuid;
 caught:=false; BEGIN PERFORM cp_start_wallet_topup(id,buyer); EXCEPTION WHEN raise_exception THEN caught:=true; END; ASSERT caught,'expired quote cannot start payment';
 ASSERT NOT has_function_privilege('authenticated','pay_order_with_wallet(bigint,uuid)','EXECUTE');
 ASSERT NOT has_function_privilege('anon','cp_credit_wallet_topup(uuid,text,text,text,numeric,text)','EXECUTE');
 ASSERT NOT has_function_privilege('authenticated','checkout_wallet_order(bigint,text,bigint,numeric)','EXECUTE');
 ASSERT NOT has_table_privilege('authenticated','cp_wallet_topup_intents','SELECT');
 ASSERT NOT has_table_privilege('authenticated','wallets','UPDATE');
 ASSERT NOT has_table_privilege('anon','wallet_transactions','TRUNCATE');
 ASSERT has_function_privilege('service_role','cp_credit_wallet_topup(uuid,text,text,text,numeric,text)','EXECUTE');
END $$;
