 SELECT '00000000-0000-4000-8000-000000000020',user_id,id,'00000000-0000-4000-8000-000000000021','doku',100000,100000,'IDR',1,current_date,100000,'IDR','starting' FROM wallets WHERE user_id='00000000-0000-4000-8000-000000000004';
INSERT INTO orders(id,buyer_id,seller_id,product_id,quantity,total_amount,total_price) SELECT n,'00000000-0000-4000-8000-000000000004','00000000-0000-4000-8000-000000000002',1,1,10000,10000 FROM generate_series(100,119) n;
-- pgbench calls this wrapper concurrently; only insufficient balance is expected.
CREATE FUNCTION fixture_spend() RETURNS void LANGUAGE plpgsql AS $$ DECLARE n integer; BEGIN
 SELECT id INTO n FROM orders WHERE id>=100 AND payment_status='pending' ORDER BY random() LIMIT 1;
 IF n IS NULL THEN RETURN; END IF;
 BEGIN PERFORM pay_order_with_wallet(n,'00000000-0000-4000-8000-000000000004');
 EXCEPTION WHEN raise_exception THEN IF SQLERRM NOT LIKE 'Insufficient%' THEN RAISE; END IF; END;
END $$;
